import { css } from '@emotion/css';
import { memo, useMemo, useState } from 'react';
import AutoSizer from 'react-virtualized-auto-sizer';

import {
  applyFieldOverrides,
  type DataFrame,
  type DataLinkClickEvent,
  type DisplayProcessor,
  type Field,
  FieldType,
  type GrafanaTheme2,
  MappingType,
  escapeStringForRegex,
} from '@grafana/data';
import {
  IconButton,
  Table,
  TableCellDisplayMode,
  type TableCustomCellOptions,
  type TableFieldOptions,
  type TableSortByFieldState,
  Tooltip,
  useStyles2,
  useTheme2,
} from '@grafana/ui';
import { TableNG } from '@grafana/ui/unstable';

import { diffColorBlindColors, diffDefaultColors } from '../FlameGraph/colors';
import { type FlameGraphDataContainer } from '../FlameGraph/dataTransform';
import { ProfileTooltipContent } from '../ProfileTooltipContent';
import { ProfileTooltipDetails } from '../ProfileTooltipDetails';
import { TOP_TABLE_COLUMN_WIDTH } from '../constants';
import { type ColorScheme, ColorSchemeDiff, type TableData } from '../types';
import { getProfileTooltipData } from '../utils';

type Props = {
  data: FlameGraphDataContainer;
  onSymbolClick: (symbol: string) => void;
  // This is used for highlighting the search button in case there is exact match.
  search?: string;
  // We use these to filter out rows in the table if users is doing text search.
  matchedLabels?: Set<string>;
  sandwichItem?: string;
  onSearch: (str: string) => void;
  onSandwich: (str?: string) => void;
  onTableSort?: (sort: string) => void;
  colorScheme: ColorScheme | ColorSchemeDiff;
  // Render the top table with TableNG instead of the legacy Table.
  useTableNG?: boolean;
  // Feature-toggle values for TableNG, passed in by the host. See FlameGraphContainer's props.
  tableRefreshEnabled?: boolean;
  contentAwareWidthsEnabled?: boolean;
};

const FlameGraphTopTableContainer = memo(
  ({
    data,
    onSymbolClick,
    search,
    matchedLabels,
    onSearch,
    sandwichItem,
    onSandwich,
    onTableSort,
    colorScheme,
    useTableNG,
    tableRefreshEnabled,
    contentAwareWidthsEnabled,
  }: Props) => {
    const table = useMemo(() => buildFilteredTable(data, matchedLabels), [data, matchedLabels]);

    const styles = useStyles2(getStyles, Boolean(useTableNG), tableRefreshEnabled);
    const theme = useTheme2();

    const [sort, setSort] = useState<TableSortByFieldState[]>([{ displayName: 'Self', desc: true }]);

    return (
      <div className={styles.topTableContainer} data-testid="topTable">
        <AutoSizer style={{ width: '100%' }}>
          {({ width, height }) => {
            if (width < 3 || height < 3) {
              return null;
            }

            const frame = buildTableDataFrame(
              data,
              table,
              width,
              onSymbolClick,
              onSearch,
              onSandwich,
              theme,
              colorScheme,
              Boolean(useTableNG),
              search,
              sandwichItem
            );

            const onSortByChange = (s: TableSortByFieldState[]) => {
              if (s && s.length) {
                onTableSort?.(s[0].displayName + '_' + (s[0].desc ? 'desc' : 'asc'));
              }
              setSort(s);
            };

            if (useTableNG) {
              // TableNG sizes its root grid to its container (CSS 100%) rather than the height prop directly,
              // so it needs a definite-size ancestor here — AutoSizer's render prop doesn't provide one on its own.
              return (
                <div style={{ width, height }}>
                  <TableNG
                    sortBy={sort}
                    sortByBehavior="managed"
                    onSortByChange={onSortByChange}
                    data={frame}
                    width={width}
                    height={height}
                    tableRefreshEnabled={tableRefreshEnabled}
                    contentAwareWidthsEnabled={contentAwareWidthsEnabled}
                    // The pane's width is already divided up between the three fixed columns and
                    // Symbol, so a horizontal scrollbar would hide columns rather than reveal them.
                    // Symbol truncates to fit instead — its full value is a click away in the flame
                    // graph, and in a narrow split pane it truncates either way.
                    preventHorizontalOverflow
                  />
                </div>
              );
            }

            return (
              <Table initialSortBy={sort} onSortByChange={onSortByChange} data={frame} width={width} height={height} />
            );
          }}
        </AutoSizer>
      </div>
    );
  }
);

FlameGraphTopTableContainer.displayName = 'FlameGraphTopTableContainer';

function buildFilteredTable(data: FlameGraphDataContainer, matchedLabels?: Set<string>) {
  // Group the data by label, we show only one row per label and sum the values
  // TODO: should be by filename + funcName + linenumber?
  let filteredTable: { [key: string]: TableData } = Object.create(null);

  // Track call stack to detect recursive calls
  const callStack: string[] = [];

  for (let i = 0; i < data.data.length; i++) {
    const value = data.getValue(i);
    const valueRight = data.getValueRight(i);
    const self = data.getSelf(i);
    const label = data.getLabel(i);
    const level = data.getLevel(i);

    // Maintain call stack based on level changes
    while (callStack.length > level) {
      callStack.pop();
    }

    // Check if this is a recursive call (same label already in call stack)
    const isRecursive = callStack.some((entry) => entry === label);

    // If user is doing text search we filter out labels in the same way we highlight them in flame graph.
    if (!matchedLabels || matchedLabels.has(label)) {
      filteredTable[label] = filteredTable[label] || {};
      filteredTable[label].self = filteredTable[label].self ? filteredTable[label].self + self : self;

      // Only add to total if this is not a recursive call
      if (!isRecursive) {
        filteredTable[label].total = filteredTable[label].total ? filteredTable[label].total + value : value;
        filteredTable[label].totalRight = filteredTable[label].totalRight
          ? filteredTable[label].totalRight + valueRight
          : valueRight;
      }
    }

    // Add current call to the stack
    callStack.push(label);
  }

  return filteredTable;
}

function buildTableDataFrame(
  data: FlameGraphDataContainer,
  table: { [key: string]: TableData },
  width: number,
  onSymbolClick: (str: string) => void,
  onSearch: (str: string) => void,
  onSandwich: (str?: string) => void,
  theme: GrafanaTheme2,
  colorScheme: ColorScheme | ColorSchemeDiff,
  useTableNG: boolean,
  search?: string,
  sandwichItem?: string
): DataFrame {
  const actionField: Field = createActionField(onSandwich, onSearch, useTableNG, search, sandwichItem);

  const symbolField: Field = {
    type: FieldType.string,
    name: 'Symbol',
    values: [],
    config: {
      // TableNG lays its columns out inside `width` minus its frame and vertical scrollbar, so
      // spelling out a width here that fills `width` leaves the grid scrolling sideways. Leaving
      // Symbol unsized instead makes it the one column TableNG sizes itself, which is the same "fill
      // whatever the fixed columns don't use" intent without having to know those chrome widths —
      // see `preventHorizontalOverflow` at the call site, which keeps Symbol inside the pane. The
      // legacy table has no such notion, so it still gets told exactly how wide to make it.
      custom: useTableNG ? {} : { width: width - actionColumnWidth - TOP_TABLE_COLUMN_WIDTH * 2 },
      links: [
        {
          title: 'Highlight symbol',
          url: '',
          onClick: (e: DataLinkClickEvent) => {
            const field: Field = e.origin.field;
            const value = field.values[e.origin.rowIndex];
            onSymbolClick(value);
          },
        },
      ],
    },
  };

  let frame;

  if (data.isDiffFlamegraph()) {
    if (!useTableNG) {
      symbolField.config.custom.width = width - actionColumnWidth - TOP_TABLE_COLUMN_WIDTH * 3;
    }

    const baselineField = createNumberField('Baseline', 'percent');
    const comparisonField = createNumberField('Comparison', 'percent');
    const diffField = createNumberField('Diff', 'percent');
    diffField.config.custom.cellOptions.type = TableCellDisplayMode.ColorText;

    const [removeColor, addColor] =
      colorScheme === ColorSchemeDiff.DiffColorBlind
        ? [diffColorBlindColors[0], diffColorBlindColors[2]]
        : [diffDefaultColors[0], diffDefaultColors[2]];

    diffField.config.mappings = [
      { type: MappingType.ValueToText, options: { [Infinity]: { text: 'new', color: addColor } } },
      { type: MappingType.ValueToText, options: { [-100]: { text: 'removed', color: removeColor } } },
      { type: MappingType.RangeToText, options: { from: 0, to: Infinity, result: { color: addColor } } },
      { type: MappingType.RangeToText, options: { from: -Infinity, to: 0, result: { color: removeColor } } },
    ];

    // For this we don't really consider sandwich view even though you can switch it on.
    const levels = data.getLevels();
    const totalTicks = levels.length ? levels[0][0].value : 0;
    const totalTicksRight = levels.length ? levels[0][0].valueRight : undefined;

    for (let key in table) {
      actionField.values.push(null);
      symbolField.values.push(key);

      const ticksLeft = table[key].total;
      const ticksRight = table[key].totalRight;

      // We are iterating over table of the data so totalTicksRight needs to be defined
      const totalTicksLeft = totalTicks - totalTicksRight!;

      const percentageLeft = Math.round((10000 * ticksLeft) / totalTicksLeft) / 100;
      const percentageRight = Math.round((10000 * ticksRight) / totalTicksRight!) / 100;

      const diff = ((percentageRight - percentageLeft) / percentageLeft) * 100;

      diffField.values.push(diff);
      baselineField.values.push(percentageLeft);
      comparisonField.values.push(percentageRight);
    }

    frame = {
      fields: [actionField, symbolField, baselineField, comparisonField, diffField],
      length: symbolField.values.length,
    };
  } else {
    const totalTicks = data.data.length > 0 ? data.getValue(0) : 0;
    const unitTitle = data.getUnitTitle();
    const selfField = createProfileValueField({
      name: 'Self',
      unit: data.selfField.config.unit,
      totalTicks,
      unitTitle,
      display: data.valueDisplayProcessor,
    });
    const totalField = createProfileValueField({
      name: 'Total',
      unit: data.valueField.config.unit,
      totalTicks,
      unitTitle,
      display: data.valueDisplayProcessor,
    });

    for (let key in table) {
      actionField.values.push(null);
      symbolField.values.push(key);
      selfField.values.push(table[key].self);
      totalField.values.push(table[key].total);
    }

    frame = { fields: [actionField, symbolField, selfField, totalField], length: symbolField.values.length };
  }

  const dataFrames = applyFieldOverrides({
    data: [frame],
    fieldConfig: {
      defaults: {},
      overrides: [],
    },
    replaceVariables: (value: string) => value,
    theme,
  });

  return dataFrames[0];
}

function createNumberField(name: string, unit?: string): Field {
  const tableFieldOptions: TableFieldOptions = {
    width: TOP_TABLE_COLUMN_WIDTH,
    align: 'auto',
    inspect: false,
    cellOptions: { type: TableCellDisplayMode.Auto },
  };

  return {
    type: FieldType.number,
    name,
    values: [],
    config: {
      unit,
      custom: tableFieldOptions,
    },
  };
}

interface ProfileValueFieldOptions {
  name: string;
  unit?: string;
  totalTicks: number;
  unitTitle: string;
  display: DisplayProcessor;
}

function createProfileValueField({ name, unit, totalTicks, unitTitle, display }: ProfileValueFieldOptions): Field {
  const field = createNumberField(name, unit);
  const cellOptions: TableCustomCellOptions = {
    type: TableCellDisplayMode.Custom,
    cellComponent: ({ field, value, frame, rowIndex }) => {
      if (typeof value !== 'number') {
        return null;
      }

      const symbolField = frame.fields.find((entry) => entry.name === 'Symbol')!;
      const selfField = frame.fields.find((entry) => entry.name === 'Self')!;
      const totalField = frame.fields.find((entry) => entry.name === 'Total')!;
      const tooltipData = getProfileTooltipData({
        displayValue: display(totalField.values[rowIndex]),
        displaySelf: display(selfField.values[rowIndex]),
        unitTitle,
        totalTicks,
      });
      const percentage = field.name === 'Self' ? tooltipData.percentSelf : tooltipData.percentValue;

      return (
        <Tooltip
          content={
            <ProfileTooltipContent label={symbolField.values[rowIndex]}>
              <ProfileTooltipDetails data={tooltipData} />
            </ProfileTooltipContent>
          }
        >
          <span dir="ltr">{percentage.toFixed(2)}%</span>
        </Tooltip>
      );
    },
  };

  field.config.custom.cellOptions = cellOptions;
  return field;
}

const actionColumnWidth = 61;

function createActionField(
  onSandwich: (str?: string) => void,
  onSearch: (str: string) => void,
  useTableNG: boolean,
  search?: string,
  sandwichItem?: string
): Field {
  const options: TableCustomCellOptions = {
    type: TableCellDisplayMode.Custom,
    cellComponent: (props) => {
      return (
        <ActionCell
          frame={props.frame}
          onSandwich={onSandwich}
          onSearch={onSearch}
          search={search}
          sandwichItem={sandwichItem}
          rowIndex={props.rowIndex}
          useTableNG={useTableNG}
        />
      );
    },
  };

  const actionFieldTableConfig: TableFieldOptions = {
    filterable: false,
    resizable: false,
    sortable: false,
    width: actionColumnWidth,
    hideHeader: true,
    inspect: false,
    align: 'auto',
    cellOptions: options,
  };

  return {
    type: FieldType.number,
    name: 'actions',
    values: [],
    config: {
      custom: actionFieldTableConfig,
    },
  };
}

type ActionCellProps = {
  frame: DataFrame;
  rowIndex: number;
  search?: string;
  sandwichItem?: string;
  onSearch: (symbol: string) => void;
  onSandwich: (symbol: string) => void;
  useTableNG: boolean;
};

function ActionCell(props: ActionCellProps) {
  const styles = getStylesActionCell();
  const symbol = props.frame.fields.find((f: Field) => f.name === 'Symbol')?.values[props.rowIndex];
  const isSearched = props.search === `^${escapeStringForRegex(String(symbol))}$`;
  const isSandwiched = props.sandwichItem === symbol;

  const searchButton = (
    <IconButton
      key="search"
      className={styles.actionCellButton}
      name={'search'}
      variant={isSearched ? 'primary' : 'secondary'}
      tooltip={isSearched ? 'Clear from search' : 'Search for symbol'}
      aria-label={isSearched ? 'Clear from search' : 'Search for symbol'}
      onClick={() => {
        props.onSearch(isSearched ? '' : symbol);
      }}
    />
  );

  const sandwichButton = (
    <IconButton
      key="sandwich"
      className={styles.actionCellButton}
      name={'gf-show-context'}
      tooltip={isSandwiched ? 'Remove from sandwich view' : 'Show in sandwich view'}
      variant={isSandwiched ? 'primary' : 'secondary'}
      aria-label={isSandwiched ? 'Remove from sandwich view' : 'Show in sandwich view'}
      onClick={() => {
        props.onSandwich(isSandwiched ? undefined : symbol);
      }}
    />
  );

  // The legacy Table right-aligns numeric cells (this actions field is FieldType.number) by rendering its
  // overflow container with direction: rtl, which flips the visual order of these two buttons to
  // sandwich-then-search even though they're written search-then-sandwich below. TableNG doesn't do that
  // right-align trick, so its custom cells render in DOM order — swap that order here for TableNG so both
  // table implementations show the buttons in the same left-to-right order.
  return (
    <div className={styles.actionCellWrapper}>
      {props.useTableNG ? (
        <>
          {sandwichButton}
          {searchButton}
        </>
      ) : (
        <>
          {searchButton}
          {sandwichButton}
        </>
      )}
    </div>
  );
}

const getStyles = (theme: GrafanaTheme2, useTableNG: boolean, tableRefreshEnabled?: boolean) => {
  return {
    topTableContainer: css({
      label: 'topTableContainer',
      padding: useTableNG ? 0 : theme.spacing(1),
      backgroundColor: useTableNG ? 'transparent' : theme.colors.background.secondary,
      height: '100%',
      // Only the legacy table paints this wrapper; TableNG is transparent and rounds its own grid.
      ...(useTableNG
        ? {}
        : {
            borderStartStartRadius: theme.shape.radius.default,
            borderStartEndRadius: theme.shape.radius.default,
          }),

      '& .rdg': {
        '--rdg-background-color': theme.colors.background.secondary,
        '--rdg-header-background-color': tableRefreshEnabled
          ? theme.components.table.headerBackground
          : theme.colors.background.secondary,
      },
    }),
  };
};

const getStylesActionCell = () => {
  return {
    actionCellWrapper: css({
      label: 'actionCellWrapper',
      display: 'flex',
      height: '24px',
    }),
    actionCellButton: css({
      label: 'actionCellButton',
      marginRight: 0,
      width: '24px',
    }),
  };
};

export { buildFilteredTable };

export default FlameGraphTopTableContainer;
